  inline const ControllerNodeConfigStatics *ControllerNodeConfig::__get_statics__()
  {
    const static ControllerNodeConfigStatics *statics;

    if (statics) // Common case
      return statics;

    boost::mutex::scoped_lock lock(dynamic_reconfigure::__init_mutex__);

    if (statics) // In case we lost a race.
      return statics;

    statics = ControllerNodeConfigStatics::get_instance();

    return statics;
  }


